//! Emit the hk steps the registry requires (`src/gen/SPEC.md`), as a Pkl
//! module a repository's `hk.pkl` imports:
//!
//! ```pkl
//! import "hk.pklith.pkl" as pklith
//! local fast = (pklith.steps) { /* the repository's own steps */ }
//! ```

use crate::catalog::{Category, Check};
use crate::registry::Registry;
use std::fmt::Write as _;

mod agents;
mod guard;
mod nix;

pub use agents::AGENTS;
pub use guard::programs;
pub use nix::{NIX, nix};

/// The generated file, next to `hk.pkl`.
pub const FILE: &str = "hk.pklith.pkl";

/// First line of every generated file (gen §C).
pub const HEADER: &str = "// generated by `pkli gen` from .pklith; do not edit\n";

/// The checks the registry uses, each once, in the order `lay` lays them:
/// category first, then catalog order (V1: an unused catalog row is never
/// emitted).
#[must_use]
pub fn used<'a>(registry: &Registry, catalog: &'a [Check]) -> Vec<&'a Check> {
    let named = |c: &&Check| registry.types.iter().any(|t| t.checks.contains(&c.id));
    let mut used: Vec<&Check> = catalog.iter().filter(named).collect();
    used.sort_by_key(|c| c.category);
    used
}

/// The Pkl module: one typed hk step per check, in two mappings. `steps`
/// run on every commit; `push` holds coverage checks, which rebuild the crate
/// instrumented and belong to push and CI. Splitting here keeps hk.pkl free
/// of filtering, which hk's own Pkl evaluator mishandles (root B12). The
/// module imports the vendored hk schema, so it evaluates offline and a wrong
/// field fails to evaluate (V4).
#[must_use]
pub fn pkl(checks: &[&Check]) -> String {
    let (push, commit): (Vec<&Check>, Vec<&Check>) = checks
        .iter()
        .partition(|c| c.category == Category::Coverage);
    format!(
        "{HEADER}import \"pkl/Config.pkl\"\n\n{}\n{}",
        mapping("steps", &commit),
        mapping("push", &push)
    )
}

fn mapping(name: &str, checks: &[&Check]) -> String {
    let body: String = checks.iter().map(|c| step(c)).collect();
    format!("{name}: Mapping<String, Config.Step> = new {{\n{body}}}\n")
}

/// The line that opens a step. `held` finds steps by it, so writing and
/// reading the generated file cannot disagree on its shape.
fn header(id: &str) -> String {
    format!("  [{}] {{\n", literal(id))
}

/// One step. No glob means whole-tree (V7); env is emitted with the step
/// that needs it (root V19).
fn step(check: &Check) -> String {
    let mut out = header(&check.id);
    if !check.globs.is_empty() {
        let globs: Vec<String> = check.globs.iter().map(|g| literal(g)).collect();
        let _ = writeln!(out, "    glob = List({})", globs.join(", "));
    }
    let _ = writeln!(out, "    check = {}", literal(&explained(check)));
    if let Some(fix) = &check.fix {
        let _ = writeln!(out, "    fix = {}", literal(fix));
    }
    out.push_str(&env(&check.env));
    out + "  }\n"
}

/// The check command, guarded and explained. A missing tool is reported as
/// missing, never as a finding (root V1); a failure prints the check's
/// message (catalog V1): what went wrong and what to do.
#[must_use]
pub fn explained(check: &Check) -> String {
    let failed = shell_quote(&format!("{}: {}", check.id, check.msg));
    format!(
        "{}{} || {{ echo {failed} >&2; exit 1; }}",
        guards(check),
        check.check
    )
}

/// One `command -v` per program the command runs (src/gen/guard.rs), each
/// naming the program it found missing.
fn guards(check: &Check) -> String {
    let guard = |tool: String| {
        let missing = shell_quote(&format!(
            "{}: {tool} is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.",
            check.id
        ));
        format!("command -v {tool} >/dev/null 2>&1 || {{ echo {missing} >&2; exit 1; }}; ")
    };
    guard::programs(&check.check)
        .into_iter()
        .map(guard)
        .collect()
}

/// Single-quote `text` for sh.
fn shell_quote(text: &str) -> String {
    format!("'{}'", text.replace('\'', "'\\''"))
}

fn env(pairs: &[String]) -> String {
    if pairs.is_empty() {
        return String::new();
    }
    let entries = pairs.iter().map(|p| {
        let (key, value) = p.split_once('=').unwrap_or((p, ""));
        format!("      [{}] = {}\n", literal(key), literal(value))
    });
    format!("    env {{\n{}    }}\n", entries.collect::<String>())
}

/// A Pkl string literal. Plain `"…"` when the text has no `"` or `\`;
/// otherwise a custom-delimited `#"…"#` with one `#` more than any run of
/// `#` after a `"` or `\`, so the text can neither close the string nor
/// start an escape. Commands need no escaping either way.
fn literal(text: &str) -> String {
    if !text.contains(['"', '\\']) {
        return format!("\"{text}\"");
    }
    let runs = text
        .split(['"', '\\'])
        .skip(1)
        .map(|s| s.chars().take_while(|c| *c == '#').count());
    let hashes = "#".repeat(runs.max().unwrap_or(0) + 1);
    format!("{hashes}\"{text}\"{hashes}")
}

/// The files gen always writes, from the repository root.
pub const FILES: [&str; 2] = [FILE, NIX];

/// Each always-generated file and its text for `checks`.
#[must_use]
pub fn outputs(checks: &[&Check]) -> [(&'static str, String); 2] {
    [(FILE, pkl(checks)), (NIX, nix(checks))]
}

/// Every file gen owns under `root`: the two it always writes, and
/// AGENTS.md when the repository placed the block's markers (gen T3).
#[must_use]
pub fn files(root: &std::path::Path) -> Vec<&'static str> {
    generated(root, &[])
        .into_iter()
        .map(|(path, _)| path)
        .collect()
}

/// Each file gen owns under `root` and its text for `checks`.
fn generated(root: &std::path::Path, checks: &[&Check]) -> Vec<(&'static str, String)> {
    let agents = read(root, AGENTS).and_then(|doc| agents::splice(&doc, checks));
    outputs(checks)
        .into_iter()
        .chain(agents.map(|text| (AGENTS, text)))
        .collect()
}

/// Write each generated file for `checks` under `root` that differs from
/// what is there (V2: a second run writes nothing). Returns what it wrote.
///
/// # Errors
///
/// The file that could not be written, with the I/O error.
pub fn write(root: &std::path::Path, checks: &[&Check]) -> Result<Vec<&'static str>, String> {
    let mut written = Vec::new();
    for (path, text) in generated(root, checks) {
        if read(root, path).as_deref() == Some(text.as_str()) {
            continue;
        }
        let full = root.join(path);
        let dir = full.parent().map_or(Ok(()), std::fs::create_dir_all);
        dir.and_then(|()| std::fs::write(&full, &text))
            .map_err(|e| format!("cannot write {path}: {e}"))?;
        written.push(path);
    }
    Ok(written)
}

/// V3: the first generated file that is not exactly what gen would write
/// for the checks `hk.pklith.pkl` holds a step for. A used check with no
/// step yet is not gen's finding but `pkli check`'s (unbacked), which is
/// what lets `pkli lay` commit one step at a time while this runs as a
/// hook. A missing file is stale.
#[must_use]
pub fn stale(root: &std::path::Path, used: &[&Check]) -> Option<&'static str> {
    let Some(module) = read(root, FILE) else {
        return Some(FILE);
    };
    let held = held(&module, used);
    generated(root, &held)
        .into_iter()
        .find(|(path, text)| read(root, path).as_deref() != Some(text.as_str()))
        .map(|(p, _)| p)
}

/// The checks among `used` whose step the generated `text` holds.
fn held<'a>(text: &str, used: &[&'a Check]) -> Vec<&'a Check> {
    let holds = |c: &&&Check| text.contains(&format!("\n{}", header(&c.id)));
    used.iter().filter(holds).copied().collect()
}

fn read(root: &std::path::Path, path: &str) -> Option<String> {
    std::fs::read_to_string(root.join(path)).ok()
}

#[cfg(test)]
mod tests {
    use super::{pkl, used};
    use crate::catalog::Check;
    use crate::registry::Registry;

    const REGISTRY: &str = r##"format 1
## checks
id|category|nix|glob|check|fix|env|msg
typos|lint|typos|**/*|typos {{files}}|-|-|m
fmt|format|rustfmt|**/*.rs, build.rs|cargo fmt --check|cargo fmt|-|m
links|lint|lychee|-|lychee "q"# x|-|A=1, B=x=y|it's broken
unused|lint|-|*|x|-|-|m
cov|coverage|-|**/*.rs|cov --check|-|-|m
## types
type|checks|min|exempt
*|typos|-|-
rs|fmt,cov|-|-
md|links|-|-
"##;

    const GENERATED: &str = r###"// generated by `pkli gen` from .pklith; do not edit
import "pkl/Config.pkl"

steps: Mapping<String, Config.Step> = new {
  ["fmt"] {
    glob = List("**/*.rs", "build.rs")
    check = "command -v cargo >/dev/null 2>&1 || { echo 'fmt: cargo is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.' >&2; exit 1; }; command -v cargo-fmt >/dev/null 2>&1 || { echo 'fmt: cargo-fmt is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.' >&2; exit 1; }; cargo fmt --check || { echo 'fmt: m' >&2; exit 1; }"
    fix = "cargo fmt"
  }
  ["typos"] {
    glob = List("**/*")
    check = "command -v typos >/dev/null 2>&1 || { echo 'typos: typos is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.' >&2; exit 1; }; typos {{files}} || { echo 'typos: m' >&2; exit 1; }"
  }
  ["links"] {
    check = ##"command -v lychee >/dev/null 2>&1 || { echo 'links: lychee is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.' >&2; exit 1; }; lychee "q"# x || { echo 'links: it'\''s broken' >&2; exit 1; }"##
    env {
      ["A"] = "1"
      ["B"] = "x=y"
    }
  }
}

push: Mapping<String, Config.Step> = new {
  ["cov"] {
    glob = List("**/*.rs")
    check = "command -v cov >/dev/null 2>&1 || { echo 'cov: cov is not on PATH; re-enter the dev shell. A MISSING TOOL, not a finding.' >&2; exit 1; }; cov --check || { echo 'cov: m' >&2; exit 1; }"
  }
}
"###;

    fn fixture() -> Result<(Registry, Vec<Check>), crate::registry::Error> {
        let registry = crate::registry::parse(REGISTRY)?;
        let catalog = crate::catalog::parse(&registry.checks)?;
        Ok((registry, catalog))
    }

    /// V1: only checks the registry names, each once, in lay order
    /// (category, then catalog order). V7: no glob means whole tree. Env
    /// goes with its step (root V19). A quote followed by `#` gets a wider
    /// delimiter.
    #[test]
    fn the_module_holds_exactly_the_used_checks() -> Result<(), crate::registry::Error> {
        let (registry, catalog) = fixture()?;
        assert_eq!(pkl(&used(&registry, &catalog)), GENERATED);
        Ok(())
    }

    const SCHEMA: &str = include_str!("../../pkl/Config.pkl");

    /// V4: the module evaluates under the vendored hk schema, offline.
    #[test]
    fn the_module_evaluates_under_the_vendored_schema() -> Result<(), Box<dyn std::error::Error>> {
        let dir = std::env::temp_dir().join(format!("pklith-gen-{}", std::process::id()));
        std::fs::create_dir_all(dir.join("pkl"))?;
        std::fs::write(dir.join("pkl/Config.pkl"), SCHEMA)?;
        std::fs::write(dir.join("hk.pklith.pkl"), GENERATED)?;
        let mut cmd = crate::proc::command("pkl", &dir);
        cmd.args(["eval", "--format", "json", "hk.pklith.pkl"]);
        let json = String::from_utf8(crate::proc::output(&mut cmd)?)?;
        assert!(
            json.contains(
                r##"; lychee \"q\"# x || { echo 'links: it'\\''s broken' >&2; exit 1; }""##
            ),
            "{json}"
        );
        Ok(std::fs::remove_dir_all(dir)?)
    }
    /// Root V21 (gen T5): neither generated file names a system, for the
    /// whole built-in catalog.
    #[test]
    fn generated_files_name_no_system() -> Result<(), crate::registry::Error> {
        let catalog = crate::catalog::builtin()?;
        let all: Vec<&Check> = catalog.iter().collect();
        for (path, text) in super::outputs(&all) {
            for system in [
                "x86_64-linux",
                "aarch64-linux",
                "aarch64-darwin",
                "x86_64-darwin",
            ] {
                assert!(!text.contains(system), "{path} names {system}");
            }
        }
        Ok(())
    }
}
